choose.when:
(
e.created_by = #{scope.userId} OR e.primary_responsible_user_id = #{scope.userId} OR EXISTS ( SELECT 1 FROM system_user scoped_user WHERE scoped_user.tenant_id = e.tenant_id AND scoped_user.id = #{scope.userId} AND scoped_user.organization_id = e.organization_id AND scoped_user.status = 1 AND scoped_user.deleted = 0 ) OR EXISTS ( SELECT 1 FROM system_user_team_membership scoped_membership WHERE scoped_membership.tenant_id = e.tenant_id AND scoped_membership.user_id = #{scope.userId} AND scoped_membership.team_organization_id = e.organization_id AND scoped_membership.deleted = 0 ) OR EXISTS ( SELECT 1 FROM equipment_responsible_person scoped_person WHERE scoped_person.tenant_id = e.tenant_id AND scoped_person.equipment_id = e.id AND scoped_person.user_id = #{scope.userId} AND scoped_person.status = 1 AND scoped_person.deleted = 0 ) OR EXISTS ( SELECT 1 FROM inspection_task scoped_inspection WHERE scoped_inspection.tenant_id = e.tenant_id AND scoped_inspection.equipment_id = e.id AND scoped_inspection.deleted = 0 AND ( scoped_inspection.assignee_user_id = #{scope.userId} OR EXISTS ( SELECT 1 FROM inspection_task_assignee scoped_assignee WHERE scoped_assignee.tenant_id = scoped_inspection.tenant_id AND scoped_assignee.task_id = scoped_inspection.id AND scoped_assignee.user_id = #{scope.userId} AND scoped_assignee.deleted = 0 ) ) ) OR EXISTS ( SELECT 1 FROM maintenance_task scoped_maintenance WHERE scoped_maintenance.tenant_id = e.tenant_id AND scoped_maintenance.equipment_id = e.id AND scoped_maintenance.deleted = 0 AND ( scoped_maintenance.assignee_user_id = #{scope.userId} OR EXISTS ( SELECT 1 FROM maintenance_task_collaborator scoped_collaborator WHERE scoped_collaborator.tenant_id = scoped_maintenance.tenant_id AND scoped_collaborator.task_id = scoped_maintenance.id AND scoped_collaborator.user_id = #{scope.userId} ) ) )
OR
e.organization_id IN
#{organizationId}
)

mapper.select:
SELECT COALESCE(SUM(planned_date = CURRENT_DATE()), 0) AS due_today,
       COALESCE(SUM(task_status IN (
           'PENDING', 'IN_PROGRESS', 'OVERDUE'
       )), 0) AS pending,
       COALESCE(SUM(
           task_status = 'OVERDUE'
           OR (
               task_status NOT IN ('COMPLETED', 'CANCELLED', 'VOIDED')
               AND due_time < CURRENT_TIMESTAMP(3)
           )
       ), 0) AS overdue,
       COALESCE(SUM(
           task_status = 'COMPLETED'
           AND DATE(completed_time) = CURRENT_DATE()
       ), 0) AS completed_today
FROM inspection_task task
WHERE task.tenant_id = #{tenantId}
  AND task.deleted = 0
  AND (
      task.assignee_user_id = #{userId}
      OR EXISTS (
          SELECT 1
          FROM inspection_task_assignee assignee
          WHERE assignee.tenant_id = task.tenant_id
            AND assignee.task_id = task.id
            AND assignee.user_id = #{userId}
      )
  )

SELECT #{startDate} AS start_date,
       #{endDate} AS end_date,
       COUNT(*) AS due,
       COALESCE(SUM(task.task_status IN ('COMPLETED', 'PENDING_REVIEW')), 0) AS completed,
       COALESCE(SUM(task.task_status NOT IN (
           'COMPLETED', 'PENDING_REVIEW', 'CANCELLED', 'VOIDED'
       )), 0) AS pending,
       COALESCE(SUM(
           task.task_status = 'OVERDUE'
           OR (
               task.task_status NOT IN (
                   'COMPLETED', 'PENDING_REVIEW', 'CANCELLED', 'VOIDED'
               )
               AND task.due_time < CURRENT_TIMESTAMP(3)
           )
       ), 0) AS overdue,
       COALESCE(SUM(EXISTS (
           SELECT 1 FROM inspection_abnormal abnormal
           WHERE abnormal.tenant_id = task.tenant_id
             AND abnormal.task_id = task.id AND abnormal.deleted = 0
       )), 0) AS abnormal,
       COALESCE(SUM(task.source_type = 'PLAN'), 0) AS plan_due,
       COALESCE(SUM(task.source_type = 'PLAN'
           AND task.task_status IN ('COMPLETED', 'PENDING_REVIEW')), 0) AS plan_completed,
       COALESCE(SUM(task.source_type = 'PLAN' AND (
           task.task_status = 'OVERDUE'
           OR (task.task_status NOT IN ('COMPLETED', 'PENDING_REVIEW', 'CANCELLED', 'VOIDED')
               AND task.due_time < CURRENT_TIMESTAMP(3))
       )), 0) AS plan_overdue,
       COALESCE(SUM(task.task_status IN ('COMPLETED', 'PENDING_REVIEW')
           AND task.completed_time >= #{startTime}
           AND task.completed_time < #{endExclusive}), 0) AS registered,
       COALESCE(SUM(task.source_type = 'QUICK_ENTRY'
           AND task.task_status IN ('COMPLETED', 'PENDING_REVIEW')
           AND task.completed_time >= #{startTime}
           AND task.completed_time < #{endExclusive}), 0) AS quick_registered,
       COUNT(DISTINCT CASE
           WHEN task.task_status IN ('COMPLETED', 'PENDING_REVIEW')
            AND task.completed_time >= #{startTime}
            AND task.completed_time < #{endExclusive}
           THEN task.equipment_id END) AS equipment_covered
FROM inspection_task task
WHERE task.tenant_id = #{tenantId} AND task.deleted = 0
  AND task.task_status NOT IN ('CANCELLED', 'VOIDED')
  AND (
      task.planned_date BETWEEN #{startDate} AND #{endDate}
      OR (
          task.completed_time >= #{startTime}
          AND task.completed_time < #{endExclusive}
      )
  )
  AND (
      task.assignee_user_id = #{userId}
      OR EXISTS (
          SELECT 1 FROM inspection_task_assignee assignee
          WHERE assignee.tenant_id = task.tenant_id
            AND assignee.task_id = task.id
            AND assignee.user_id = #{userId}
      )
  )

SELECT COALESCE(SUM(planned_date = CURRENT_DATE()), 0) AS due_today,
       COALESCE(SUM(task_status IN (
           'PENDING', 'IN_PROGRESS', 'PAUSED',
           'PENDING_CONFIRMATION', 'OVERDUE'
       )), 0) AS pending,
       COALESCE(SUM(
           task_status = 'OVERDUE'
           OR (
               task_status NOT IN ('COMPLETED', 'CANCELLED', 'VOIDED')
               AND due_time < CURRENT_TIMESTAMP(3)
           )
       ), 0) AS overdue,
       COALESCE(SUM(
           task_status = 'COMPLETED'
           AND DATE(completed_time) = CURRENT_DATE()
       ), 0) AS completed_today
FROM maintenance_task task
WHERE task.tenant_id = #{tenantId}
  AND task.deleted = 0
  AND (
      task.assignee_user_id = #{userId}
      OR EXISTS (
          SELECT 1
          FROM maintenance_task_collaborator collaborator
          WHERE collaborator.tenant_id = task.tenant_id
            AND collaborator.task_id = task.id
            AND collaborator.user_id = #{userId}
      )
  )
